CREATE DATABASE IF NOT EXISTS activa_el_turismo;
USE activa_el_turismo;

CREATE TABLE IF NOT EXISTS usuarios (
    id_usu       INT AUTO_INCREMENT PRIMARY KEY,
    nombre_usu   VARCHAR(100)  NOT NULL,
    correo_usu   VARCHAR(150)  NOT NULL UNIQUE,
    password_usu VARCHAR(255)  NOT NULL,
    rol_usu      ENUM('admin','editor','colaborador') DEFAULT 'editor'
);

CREATE TABLE IF NOT EXISTS categorias (
    id_cat     INT AUTO_INCREMENT PRIMARY KEY,
    nombre_cat VARCHAR(100) NOT NULL,
    slug_cat   VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS etiquetas (
    id_eti   INT AUTO_INCREMENT PRIMARY KEY,
    nom_eti  VARCHAR(100) NOT NULL,
    slug_eti VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS noticias (
    id INT AUTO_INCREMENT PRIMARY KEY,
    fecha DATE NOT NULL,
    titulo VARCHAR(255) NOT NULL,
    subtitulo VARCHAR(255),
    autor VARCHAR(100) NOT NULL,
    cuerpo TEXT NOT NULL,
    imagen_path VARCHAR(255),
    pie_imagen VARCHAR(255),
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    slug_not VARCHAR(255) NOT NULL UNIQUE,
    id_cat INT, 
    FOREIGN KEY (id_cat) REFERENCES categorias(id_cat) ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE IF NOT EXISTS noticias_etiquetadas (
    id INT NOT NULL,
    id_eti INT NOT NULL,
    PRIMARY KEY (id, id_eti)
);

INSERT INTO `noticias` (`id`, `fecha`, `titulo`, `subtitulo`, `autor`, `cuerpo`, `imagen_path`, `pie_imagen`, `fecha_creacion`, `slug_not`, `id_cat`) VALUES (NULL, '2022-12-19', 'Tocopilla y María Elena apuestan por el turismo sostenible para impulsar el desarrollo local', 'Patrimonio histórico, turismo astronómico y nuevas estrategias de gestión posicionan a ambas comunas como destinos con alto potencial en la Región de Antofagasta.', 'Patricio Videla', 'La puesta en valor del patrimonio salitrero, la capacitación de capital humano y el fortalecimiento de una oferta turística sustentable son parte de la estrategia que busca convertir a Tocopilla y María Elena en referentes del turismo regional, generando nuevas oportunidades para sus comunidades.\r\n\r\nEl más reciente episodio del podcast Activa el Turismo abordó el potencial turístico de las comunas de Tocopilla y María Elena, destacando las iniciativas que buscan consolidar ambos territorios como destinos atractivos a través de una planificación estratégica y sostenible.\r\n\r\nEn Tocopilla, uno de los principales atractivos es la histórica Oficina Salitrera de Chacabuco, declarada Monumento Nacional y reconocida como un importante símbolo de la memoria pampina. A este patrimonio se suman 21 atractivos turísticos y más de un centenar de empresas ligadas al rubro, fortaleciendo la oferta local.\r\n\r\nLa comuna también enfrenta el desafío de aprovechar el tránsito anual de más de 2,2 millones de vehículos que circulan por la zona, una oportunidad que podría traducirse en un importante impulso para la economía local. Asimismo, el avance del proceso de descarbonización y la incorporación de energías limpias contribuyen a mejorar las condiciones para el desarrollo del turismo.\r\n\r\nEn tanto, María Elena, recientemente reconocida como Zona de Interés Turístico (ZOIT), busca poner en valor sus nueve monumentos nacionales y ampliar su oferta mediante experiencias de turismo astronómico, etnográfico y patrimonial, destacando lugares como Cuchucho y Quillagua.\r\n\r\nEl episodio también resaltó la importancia de formar guías turísticos especializados, capaces de transmitir la historia, cultura e identidad de cada territorio, fortaleciendo la experiencia de quienes visitan la zona.\r\n\r\nCon estas iniciativas, ambas comunas avanzan hacia un modelo de turismo que busca equilibrar el crecimiento económico, la conservación del patrimonio y la protección del medio ambiente, consolidando una oferta con identidad y proyección para el norte de Chile.', 'img/1783958132_Captura_de_pantalla_2026_07_13_115444.png', 'Capítulo del Podcast \"En este último capítulo reflexionamos junto a Raúl Catalán, integrante de la empresa Cyties I&D\"', '2026-07-13 11:55:32', 'tocopilla-y-maria-elena-apuestan-por-el-turismo-sostenible-para-impulsar-el-desarrollo-local', '1')
INSERT INTO `noticias` (`id`, `fecha`, `titulo`, `subtitulo`, `autor`, `cuerpo`, `imagen_path`, `pie_imagen`, `fecha_creacion`, `slug_not`, `id_cat`) VALUES (NULL, '2022-12-19', 'María Elena fortalece su identidad patrimonial para impulsar el turismo en el norte de Chile', 'El último campamento salitrero en funcionamiento apuesta por preservar su historia, fortalecer el trabajo de los guías turísticos y consolidarse como un destino de interés cultural en la Región de Antofagasta.', 'Patricio Videla', 'El patrimonio industrial, la memoria pampina y el compromiso de la comunidad son los pilares con los que María Elena busca posicionarse como un destino turístico único, destacando su historia ligada al salitre y el trabajo colaborativo para potenciar la actividad en la comuna.\r\n\r\nEn un nuevo episodio del podcast Activa el Turismo, Gustavo Araya, representante de la Asociación de Guías de Turismo de María Elena, destacó el valor histórico y cultural de la comuna, reconocida por ser el último campamento salitrero en operación a nivel mundial y un referente del patrimonio industrial del norte de Chile.\r\n\r\nDurante la conversación, se abordó la importancia de conservar la identidad pampina mientras la comuna avanza hacia un proceso de modernización. En este contexto, la historia del ciclo del salitre, el legado de las antiguas oficinas y la influencia cultural que marcaron el desarrollo del territorio se presentan como elementos clave para fortalecer la oferta turística.\r\n\r\nLa Asociación de Guías de Turismo trabaja en la difusión de este patrimonio mediante recorridos que incluyen museos, sitios históricos y circuitos patrimoniales, recibiendo tanto visitantes nacionales como extranjeros interesados en conocer la historia de la industria salitrera y su impacto en la Región de Antofagasta.\r\n\r\nEl episodio también destacó la necesidad de fortalecer la colaboración entre el municipio, el sector privado y las organizaciones locales para desarrollar estrategias que permitan posicionar a María Elena como un destino turístico sostenible. Entre sus principales atractivos se encuentran monumentos históricos como el Embalse de Loma, además de una oferta de alojamiento y gastronomía local que complementa la experiencia de los visitantes.\r\n\r\nFinalmente, Gustavo Araya hizo un llamado a valorar la identidad de María Elena y a promover su riqueza patrimonial como una oportunidad para impulsar el desarrollo económico y cultural de la comuna, preservando la memoria de uno de los territorios más emblemáticos de la historia salitrera de Chile.', 'img/1783958723_Captura_de_pantalla_2026_07_13_120501.png', 'Capítulo del Podcast \"Gustavo Araya De la Asociación de Guías de Turismo de María Elena\"', '2026-07-13 12:05:23', 'maria-elena-fortalece-su-identidad-patrimonial-para-impulsar-el-turismo-en-el-norte-de-chile', '1')
INSERT INTO `noticias` (`id`, `fecha`, `titulo`, `subtitulo`, `autor`, `cuerpo`, `imagen_path`, `pie_imagen`, `fecha_creacion`, `slug_not`, `id_cat`) VALUES (NULL, '2022-12-13', 'El sandboard se consolida como una nueva experiencia turística en Antofagasta', 'Omar Martínez Ibarbe destaca el potencial de las dunas de Roca Roja para impulsar el turismo de aventura y llama a fortalecer el trabajo colaborativo entre los actores del sector.', 'Patricio Videla', 'El turismo deportivo y la conservación del patrimonio natural se posicionan como una oportunidad para diversificar la oferta turística de Antofagasta. En un nuevo episodio de Activa el Turismo, Omar Martínez Ibarbe compartió su experiencia promoviendo el sandboard como una actividad que combina deporte, naturaleza y desarrollo local.\r\n\r\nDurante la entrevista, el fundador de una agencia especializada en sandboard explicó cómo las dunas de Roca Roja, ubicadas al sur de Antofagasta, se han convertido en un escenario ideal para quienes buscan vivir experiencias al aire libre. Con más de una década dedicado a esta disciplina, Martínez ha impulsado iniciativas que acercan este deporte a turistas nacionales e internacionales, promoviendo además la práctica segura mediante guías e instructores certificados.\r\n\r\nMás allá de la experiencia deportiva, el entrevistado enfatizó la importancia de proteger las dunas como parte del patrimonio natural de la región. En este sentido, destacó el trabajo que realizan para fomentar el turismo responsable, incentivando el cuidado del entorno y promoviendo el reconocimiento de estos espacios como un atractivo de alto valor para Antofagasta.\r\n\r\nEl episodio también abordó los desafíos que enfrenta el turismo regional. Según Martínez, la ciudad aún tiene un amplio potencial por desarrollar y requiere una mayor articulación entre agencias de turismo, hoteles, empresas de transporte y organismos públicos para ofrecer experiencias integradas que incentiven a los visitantes a permanecer más tiempo en la zona.\r\n\r\nLa experiencia adquirida en destinos consolidados como San Pedro de Atacama también permitió reflexionar sobre la importancia de fortalecer las redes de colaboración, el marketing turístico y la promoción conjunta de los distintos atractivos de la región. A juicio del entrevistado, la cooperación entre operadores permitiría diversificar la oferta y posicionar a Antofagasta como un destino capaz de combinar patrimonio, naturaleza, deportes de aventura y cielos privilegiados.\r\n\r\nFinalmente, Omar Martínez invitó a conocer las dunas de Roca Roja a través de recorridos que incluyen instrucción profesional, equipamiento especializado y actividades diseñadas para personas de distintos niveles de experiencia. La iniciativa busca no solo fomentar el turismo de aventura, sino también contribuir al desarrollo sostenible del territorio mediante la valorización de sus paisajes naturales y el trabajo conjunto de la comunidad turística.', 'img/1783959675_Captura_de_pantalla_2026_07_13_122056.png', 'Capítulo del Podcast \"Activa El Turismo, conversamos Omar Martínez Ibarbe\"', '2026-07-13 12:21:15', 'el-sandboard-se-consolida-como-una-nueva-experiencia-turistica-en-antofagasta', '1')
INSERT INTO `noticias` (`id`, `fecha`, `titulo`, `subtitulo`, `autor`, `cuerpo`, `imagen_path`, `pie_imagen`, `fecha_creacion`, `slug_not`, `id_cat`) VALUES (NULL, '2022-11-29', 'Chango Tour apuesta por la fotografía para transformar la experiencia turística en San Pedro de Atacama', 'La iniciativa liderada por Pedro FuenteAlba combina fotografía, patrimonio y relatos locales para ofrecer una nueva forma de descubrir los paisajes y la cultura del desierto.', 'Patricio Videla', 'La innovación en turismo no solo está en los destinos, sino también en la forma de vivirlos. En un nuevo episodio de Activa el Turismo, Pedro FuenteAlba, gerente de Chango Tour, presentó una propuesta que integra fotografía, interpretación patrimonial y participación de las comunidades locales para enriquecer la experiencia de quienes visitan San Pedro de Atacama.\r\n\r\nDurante la conversación, FuenteAlba explicó que Chango Tour nació con el propósito de poner en valor no solo los reconocidos paisajes de San Pedro de Atacama, sino también otros destinos de la Región de Antofagasta, especialmente la costa, buscando diversificar la oferta turística y conectar distintos territorios mediante experiencias innovadoras.\r\n\r\nUno de los principales ejes de su propuesta es la denominada \"fotografía cultural\", un concepto que combina imágenes de alta calidad con relatos históricos y patrimoniales. Más que registrar un paisaje, la iniciativa busca que cada fotografía refleje la historia, el contexto y la identidad del lugar visitado, permitiendo que los turistas comprendan el valor cultural de los destinos mientras disfrutan de la experiencia.\r\n\r\nEl emprendimiento también ha desarrollado las Astrosesiones, una actividad que une fotografía nocturna, observación del cielo y divulgación astronómica. La experiencia incluye una introducción sobre los cuerpos celestes visibles según la época del año, seguida de una sesión fotográfica bajo algunos de los cielos más privilegiados del mundo, transformando el astroturismo en una vivencia educativa y memorable.\r\n\r\nOtro aspecto destacado del episodio fue el trabajo colaborativo con las comunidades atacameñas. FuenteAlba explicó que actualmente desarrollan rutas de etnoturismo junto a habitantes de localidades como Toconao, quienes participan como guías y relatores de su propia historia. Esta iniciativa busca preservar el patrimonio inmaterial, rescatando conocimientos y tradiciones transmitidas de generación en generación para convertirlos en parte de la experiencia turística.\r\n\r\nFinalmente, el entrevistado señaló que el turismo del futuro debe construirse junto a las comunidades locales, fortaleciendo la identidad cultural y promoviendo experiencias auténticas que permitan conservar el patrimonio mientras generan nuevas oportunidades de desarrollo para los habitantes del territorio. Con propuestas que integran naturaleza, fotografía e historia, Chango Tour busca demostrar que el turismo puede convertirse en una herramienta para valorar y proyectar la riqueza cultural de la Región de Antofagasta.', 'img/1783959960_Captura_de_pantalla_2026_07_13_122544.png', 'Capítulo del Podcast \"Entrevistamos a Pedro FuenteAlba, Gerente de Chango Tour\"', '2026-07-13 12:26:00', 'chango-tour-apuesta-por-la-fotografia-para-transformar-la-experiencia-turistica-en-san-pedro-de-atacama', '1')

